// Add a "Gallery" item to the header menu, right after "Design", on every page.
//
// The nav is shared chrome repeated on each flattened page (desktop + mobile
// copies). This inserts the Gallery link after each Design menu item so the
// gallery is reachable site-wide. Idempotent: pages that already have it are
// skipped. gallery.html is generated by build-gallery-page.mjs and is excluded
// here (it inherits the nav from its chrome source).
//
// Run: node scripts/add-gallery-nav.mjs

import { readdir, readFile, writeFile } from 'node:fs/promises';

const DESIGN_CLOSE = '>Design</a></li>';
const GALLERY_LI =
  '\n<li class="menu-item menu-item-type-post_type menu-item-object-page menu-item-gallery">' +
  '<a href="gallery.html">Gallery</a></li>';

const files = (await readdir('.')).filter((f) => f.endsWith('.html') && f !== 'gallery.html');

let changed = 0;
for (const file of files) {
  const html = await readFile(file, 'utf8');
  if (html.includes('menu-item-gallery')) { console.log(`skip  ${file} (already has Gallery)`); continue; }
  if (!html.includes(DESIGN_CLOSE)) { console.log(`WARN  ${file} (no Design menu item found)`); continue; }
  const out = html.split(DESIGN_CLOSE).join(DESIGN_CLOSE + GALLERY_LI);
  const added = (out.match(/menu-item-gallery/g) || []).length;
  await writeFile(file, out, 'utf8');
  console.log(`PASS  ${file} (+${added} Gallery link${added === 1 ? '' : 's'})`);
  changed++;
}
console.log(`\nupdated ${changed} file(s)`);
